use std::{future::{Future, poll_fn}, io::Write, os::unix::net::UnixStream,
    pin::Pin, sync::{Arc, OnceLock, atomic::{AtomicBool, AtomicUsize, Ordering}},
    task::{Context, Poll}, time::{Duration, Instant}};
use tokio::io::{AsyncRead, ReadBuf};

struct Busy {
    signal: Option<UnixStream>,
    start: Arc<OnceLock<Instant>>,
    done: Arc<AtomicBool>,
    polls: Arc<AtomicUsize>,
}
impl Future for Busy {
    type Output = ();
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if self.done.load(Ordering::Relaxed) { return Poll::Ready(()); }
        if let Some(mut writer) = self.signal.take() {
            self.start.set(Instant::now()).unwrap();
            writer.write_all(&[1]).unwrap();
        }
        self.polls.fetch_add(1, Ordering::Relaxed);
        let until = Instant::now() + Duration::from_micros(50);
        while Instant::now() < until { std::hint::spin_loop(); }
        cx.waker().wake_by_ref();
        Poll::Pending
    }
}

fn trial(interval: u32) -> (usize, u128) {
    tokio::runtime::Builder::new_current_thread().enable_all().event_interval(interval)
        .build().unwrap().block_on(async {
        let (reader, writer) = UnixStream::pair().unwrap();
        reader.set_nonblocking(true).unwrap();
        let mut reader = tokio::net::UnixStream::from_std(reader).unwrap();
        let done = Arc::new(AtomicBool::new(false));
        let polls = Arc::new(AtomicUsize::new(0));
        let start = Arc::new(OnceLock::<Instant>::new());
        let (armed, ready) = tokio::sync::oneshot::channel();
        let (d, p, s) = (done.clone(), polls.clone(), start.clone());
        let read = tokio::spawn(async move {
            let mut armed = Some(armed);
            let mut byte = [0];
            poll_fn(|cx| {
                let mut buf = ReadBuf::new(&mut byte);
                let result = Pin::new(&mut reader).poll_read(cx, &mut buf);
                if result.is_pending() && let Some(armed) = armed.take() { let _ = armed.send(()); }
                result
            }).await.unwrap();
            let result = (p.load(Ordering::Relaxed), s.get().unwrap().elapsed().as_micros());
            d.store(true, Ordering::Relaxed);
            assert_eq!(byte, [1]);
            result
        });
        ready.await.unwrap();
        let mut tasks = vec![];
        let mut writer = Some(writer);
        for _ in 0..64 {
            tasks.push(tokio::spawn(Busy {signal: writer.take(), start: start.clone(),
                done: done.clone(), polls: polls.clone()}));
        }
        let result = read.await.unwrap();
        for task in tasks { task.await.unwrap(); }
        result
    })
}

fn main() {
    for round in 1..=10 {
        let order = if round % 2 == 1 { [61, 16] } else { [16, 61] };
        for interval in order {
            let (polls, us) = trial(interval);
            println!("{{\"round\":{round},\"event_interval\":{interval},\"polls_after_io_ready\":{polls},\"io_delivery_us\":{us}}}");
        }
    }
}

